head.b:skin:


        /* ---------------------------------------------------------------------------------------
        [STEPS 1-100] TITAN CORE DESIGN SYSTEM - AUDITED v67.0
        --------------------------------------------------------------------------------------- */
        :root {
            --primary: #ce1212; --primary-dark: #a00d0d;
            --secondary: #37373f; --accent: #ffc107;
            --bg-body: #f8f9fa; --bg-card: #ffffff;
            --text-main: #1d1d1f; --text-muted: #86868b;
            --font-main: "Inter", sans-serif; --font-accent: "Amatic SC", sans-serif;
            --font-mono: "JetBrains Mono", monospace;
            --transition: 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
            --z-navbar: 1030; --z-mobile-nav: 1050; --z-toast: 1100;
            --shadow-sm: 0 4px 12px rgba(0,0,0,0.03);
            --shadow-lg: 0 20px 60px rgba(0,0,0,0.08);
            --radius-xl: 24px;
        }

        [data-theme='dark'
] { 
            --bg-body: #0a0a0c; --bg-card: #1c1c1e; 
            --text-main: #f5f5f7; --text-muted: #a1a1a6; 
        }

        /* [FLUID TYPOGRAPHY] */
        h1, .display-1 { font-size: clamp(2.2rem, 6vw, 4rem); line-height: 1.1; font-weight: 800; letter-spacing: -1.5px; }
        h2, .display-2 { font-size: clamp(1.8rem, 5vw, 3.2rem); font-weight: 700; }
        h4, .product-card h4 { font-size: clamp(1.05rem, 2.5vw, 1.25rem) !important; line-height: 1.4; font-weight: 700; }
        .lead { font-size: clamp(0.95rem, 2vw, 1.15rem); line-height: 1.6; }

        body { font-family: var(--font-main); background: var(--bg-body); color: var(--text-main); padding-top: 85px; padding-bottom: 95px; transition: background 0.3s; overflow-x: hidden; -webkit-font-smoothing: antialiased; }
        body.rtl { direction: rtl; text-align: right; }

        #scroll-fill { position: fixed; top: 0; left: 0; height: 4px; background: var(--primary); z-index: 2100; width: 0%; transition: 0.1s; box-shadow: 0 0 15px var(--primary); }

        /* [STEP 86] FAB POSITIONING */
        .fab-support { position: fixed; right: 25px; bottom: 105px; z-index: 1040; background: #25d366; width: 75px; height: 75px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 2.4rem; box-shadow: 0 12px 35px rgba(37,211,102,0.4); text-decoration: none; animation: pulseFab 2s infinite; }
        @keyframes pulseFab { 0% { transform:scale(1); } 70% { transform:scale(1.05); } 100% { transform:scale(1); } }
        @media (min-width: 992px) { .fab-support { bottom: 40px; } }

        /* [STEP 86/97] GRID ARCHITECTURE */
        .product-card { border: none; border-radius: var(--radius-xl); background: var(--bg-card); box-shadow: var(--shadow-sm); position: relative !important; display: flex; flex-direction: column; height: 100%; overflow: hidden; transition: var(--transition); border: 1px solid rgba(0,0,0,0.02); }
        .product-card:hover { transform: translateY(-10px); box-shadow: var(--shadow-lg); }

        .product-img-wrapper { position: relative; width: 100%; aspect-ratio: 4 / 3; overflow: hidden; background: #eee; }
        .product-img { width: 100%; height: 100%; object-fit: cover; cursor: pointer; transition: 0.8s ease; }

        /* [STEP 30] SKELETON LOADERS */
        .skeleton { background: #e0e0e0; border-radius: 4px; animation: shimmer 1.5s infinite linear; background: linear-gradient(to right, #eeeeee 8%, #dddddd 18%, #eeeeee 33%); background-size: 1000px 100%; }
        @keyframes shimmer { 0% { background-position: -1000px 0; } 100% { background-position: 1000px 0; } }
        .sk-img { height: 200px; width: 100%; border-radius: var(--radius-xl) var(--radius-xl) 0 0; }
        .sk-text { height: 20px; width: 80%; margin: 15px auto; }

        @media (max-width: 576px) { 
            .product-grid-item { width: 100% !important; flex: 0 0 100% !important; max-width: 100% !important; margin-bottom: 35px !important; }
            .product-img-wrapper { aspect-ratio: 1 / 1 !important; } 
            .product-card h4 { font-size: 1.4rem !important; }
            .p-5 { padding: 1.8rem !important; }
        }

        /* [STEP 11] UI ACTIONS */
        .wish-btn { position: absolute !important; top: 15px; right: 15px; z-index: 45; background: rgba(255,255,255,0.95); border: none; border-radius: 50%; width: 44px; height: 44px; display: flex; align-items: center; justify-content: center; color: #888; box-shadow: 0 4px 15px rgba(0,0,0,0.1); transition: 0.3s; cursor: pointer; }
        .wish-btn.active { color: var(--primary); transform: scale(1.1); background: #fff; }
        .compare-toggle { position: absolute; top: 15px; left: 15px; z-index: 45; background: rgba(255,255,255,0.95); border: none; border-radius: 12px; padding: 6px 14px; font-size: 0.6rem; font-weight: 800; text-transform: uppercase; color: #333; cursor: pointer; transition: 0.2s; }
        .compare-toggle:hover { background: var(--primary); color: #fff; }

        /* [QUANTITY & UX] */
        .qty-box { display: flex; align-items: center; gap: 12px; background: rgba(0,0,0,0.05); padding: 10px 20px; border-radius: 50px; }
        .qty-btn { cursor: pointer; font-weight: 800; color: var(--primary); font-size: 1.4rem; user-select: none; width: 35px; height: 35px; display: flex; align-items: center; justify-content: center; border-radius: 50%; transition: 0.2s; border: none; background: none; }

        /* [STEP 88] LOYALTY WIDGET */
        .loyalty-widget { background: linear-gradient(135deg, #1d1d1f, #3a3a3c); color: #fff; padding: 30px; border-radius: 30px; margin-bottom: 35px; position: relative; overflow: hidden; border: 1px solid rgba(255,255,255,0.1); box-shadow: 0 20px 40px rgba(0,0,0,0.2); display: none; }

        /* HEADER & TOOLBAR - FIXED BARS */
        .header { background: rgba(255,255,255,0.85); backdrop-filter: blur(25px); height: 90px; z-index: var(--z-navbar); border-bottom: 1px solid rgba(0,0,0,0.05); transition: background 0.3s; }
        [data-theme='dark'] .header { background: rgba(28,28,30,0.85); }
        .settings-select { background: #f0f0f2; border: none; border-radius: 10px; font-weight: 700; font-size: 0.85rem; padding: 8px 15px; cursor: pointer; color: var(--text-main); transition: 0.2s; -webkit-appearance: none; }
        [data-theme='dark'] .settings-select { background: #2c2c2e; color: #fff; }

        .mobile-toolbar { position: fixed; bottom: 0; left: 0; width: 100%; height: 80px; background: var(--bg-card); display: flex; justify-content: space-around; align-items: center; z-index: var(--z-mobile-nav); border-top: 1px solid rgba(0,0,0,0.1); padding-bottom: env(safe-area-inset-bottom); }
        .mobile-toolbar a, .mobile-toolbar button { color: var(--text-main); font-size: 1.8rem; background:none; border:none; transition: 0.3s; position: relative; }

        /* MODULE VISIBILITY ENGINE */
        .module-section { display: none !important; padding: 40px 0; min-height: 90vh; width: 100%; opacity: 0; animation: fadeIn 0.5s forwards; }
        .module-section.active { display: block !important; opacity: 1; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

        .hidden { display: none !important; }

        /* Swatches */
        .swatch-group { display: flex; gap: 10px; }
        .swatch-item { width: 35px; height: 35px; border-radius: 50%; cursor: pointer; border: 2px solid transparent; }
        .swatch-item.active { border-color: var(--text-main); transform: scale(1.1); }

        /* Cart Item */
        .cart-item-row { display: flex; justify-content: space-between; align-items: center; padding: 20px 0; border-bottom: 1px solid rgba(0,0,0,0.05); }
        .btn-trash { background: none; border: none; color: var(--primary); font-size: 1.5rem; cursor: pointer; transition: 0.2s; }
        .btn-trash:hover { transform: scale(1.2); color: #ff0000; }

        .breadcrumb-flat { margin-bottom: 30px; font-size: 0.9rem; color: var(--text-muted); font-weight: 600; }
        .breadcrumb-flat span { margin: 0 10px; }
        .breadcrumb-flat a { color: var(--text-main); text-decoration: none; }

body.script:
   //
   /**
    * ELGOURARI ENTERPRISE MONOLITH v67.0 (1500+ LINES)
    * AUTHOR: elgourari project
    * STATUS: Production Verified.
    * FIXED: WhatsApp Position. Language State Persistence. 
    */
   const App = (function() {
       "use strict";

       // --- GLOBAL MONOLITHIC STATE ---
       let state = {
           catalog: [],
           cart: JSON.parse(localStorage.getItem('sushi_cart')) || [],
           wishlist: JSON.parse(localStorage.getItem('sushi_wishlist')) || [],
           compare: [],
           view: 'grid',
           promo: 0,
           tip: 0,
           currency: localStorage.getItem('sushi_currency') || 'DH',
           lang: localStorage.getItem('sushi_lang') || 'en',
           rates: { 'DH': 1, 'USD': 0.10, 'EUR': 0.09 },
           settings: { maintenance: false, vat: 0.20, brand: 'SushiElite', pushEnabled: localStorage.getItem('sushi_push') || 'false' },
           selectedVariant: { color: 'Standard Black' },
           quickViewQty: 1,
           coords: null
       };

       const translations = {
           en: { nav_home: "Home", nav_menu: "Menu", cat_title: "Curated Selection", hero_subtitle: "Enterprise v67.0: Reactive language engine active. WhatsApp FAB repositioned.", btn_explore: "Order Now" },
           fr: { nav_home: "Accueil", nav_menu: "Menu", cat_title: "Sélection Pro", hero_subtitle: "Monolithe Enterprise v67.0: Langue réactive. Position WhatsApp corrigée.", btn_explore: "Commander" },
           ar: { nav_home: "الرئيسية", nav_menu: "القائمة", cat_title: "قائمة متميزة", hero_subtitle: "المؤسسة v67.0: تمت مزامنة اللغات. تم تصحيح موقع واتساب.", btn_explore: "اطلب الآن" }
       };

       const BLOG_URL = 'https://eventsushi.blogspot.com';

       // --- INTERNAL CORE HANDLERS (SEQUENTIAL DEFINITIONS) ---

       function checkPushStatus() {
           if (state.settings.pushEnabled === 'false') {
               setTimeout(() => { const optin = document.getElementById('push-optin'); if(optin) optin.style.display = 'flex'; }, 8000);
           }
       }

       function setupFlatpickrModules() {
           const picker = document.getElementById('delivery-time');
           if(picker) flatpickr("#delivery-time", { enableTime: true, dateFormat: "Y-m-d H:i", minDate: "today"
});
       }

       function applyActiveTranslation() {
           const tData = translations[state.lang] || translations['en'];
           document.querySelectorAll('[data-i18n]').forEach(el => {
               const k = el.getAttribute('data-i18n');
               if(tData[k]) el.innerText = tData[k];
           });
           document.body.className = state.lang === 'ar' ? 'rtl' : '';
           if(document.getElementById('lang-selector')) document.getElementById('lang-selector').value = state.lang;
           if(document.getElementById('currency-selector')) document.getElementById('currency-selector').value = state.currency;
       }

       function normalizeCommerceState() {
           state.cart = state.cart.map(item => ({ ...item, qty: Number(item.qty) || 1, price: Number(item.price) || 0 }));
           state.wishlist = state.wishlist.map(item => ({ ...item, sku: item.sku || 'SKU-000', price: Number(item.price) || 0 }));
           localStorage.setItem('sushi_cart', JSON.stringify(state.cart));
           localStorage.setItem('sushi_wishlist', JSON.stringify(state.wishlist));
       }

       function fetchCatalogueApiData() {
           const sNode = document.createElement('script');
           sNode.src = `${BLOG_URL}/feeds/posts/default?alt=json-in-script&callback=App.parseCatalog&max-results=100`;
           document.body.appendChild(sNode);
       }

       function renderGridView(items, rootId = 'product-grid-root') {
           const container = document.getElementById(rootId);
           if (!container) return;
           if(items.length === 0 && state.catalog.length === 0) {
               container.innerHTML = Array(6).fill(`<div class="col-lg-4 col-12 mb-3"><div class="skeleton sk-img"></div><div class="skeleton sk-text"></div></div>`).join('');
               return;
           }
           container.className = `row gy-5 ${state.view}-view`;
           container.innerHTML = items.map(item => {
               const absIdx = state.catalog.findIndex(c => c.sku === item.sku);
               const isFav = state.wishlist.some(w => w.title === item.title);
               return `
               <div class="col-lg-4 col-12 product-grid-item mb-1" data-aos="fade-up">
                   <div class="product-card shadow-sm border-0">
                       <button class="compare-toggle shadow-sm" onclick="App.addToCompare(${absIdx})">Analyze</button>
                       <button class="wish-btn ${isFav ? 'active' : ''}" onclick="App.toggleWishlist(${absIdx})"><i class="bi bi-heart-fill"></i></button>
                       <div class="product-img-wrapper" onclick="App.openQuickView(${absIdx})">
                           <img src="${item.img}" class="product-img" loading="lazy" />
                       </div>
                       <div class="p-5 text-center">
                           <div class="star-rating mb-3 text-warning"><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-half"></i></div>
                           <h4 class="fw-bold text-truncate m-0 mb-3">${item.title}</h4>
                           <div class="d-flex justify-content-center align-items-center gap-3">
                               <span class="text-danger fw-bold fs-4">${formatPriceString(item.price)}</span>
                               <span class="badge bg-light text-muted small border py-2 px-3 fw-bold">ID: ${(item.sku || 'N/A').toString().substring(0,8)}</span>
                           </div>
                           <button class="btn btn-danger w-100 rounded-pill mt-4 py-3 fw-bold shadow-xl transition-all hover-up" onclick="App.addToCart(${absIdx})">Add to Order Bag</button>
                       </div>
                   </div>
               </div>`;
           }).join('') || '<div class="py-5 text-center col-12 text-muted fs-4">No records matched selection.</div>';
       }

       function renderWishlistView() { renderGridView(state.wishlist, 'wishlist-grid-root'); }

       function renderCartView() {
           const root = document.getElementById('cart-items-list');
           if (!root) return;
           const sub = state.cart.reduce((a, b) => a + (Number(b.price) * Number(b.qty)), 0);
           const tax = sub * state.settings.vat;
           const total = calculateCommerceTotalLogic(sub);
           root.innerHTML = state.cart.map((item, idx) => `
               <div class="cart-item-row" data-aos="fade-left">
                   <div class="d-flex align-items-center gap-3">
                       <img src="${item.img}" class="rounded-4 shadow-sm" style="width:75px; height:75px; object-fit:cover; border:2px solid #fff" />
                       <div>
                           <b class="fs-5 d-block" style="letter-spacing:-0.5px">${item.title}</b>
                           <small class="text-muted fw-bold text-uppercase opacity-75">${formatPriceString(item.price)} / Unit</small>
                       </div>
                   </div>
                   <div class="d-flex align-items-center gap-5">
                       <div class="qty-box shadow-lg">
                           <button class="qty-btn" onclick="App.updateQuantity(${idx}, -1)">-</button>
                           <span class="fw-bold px-3 fs-5">${item.qty}</span>
                           <button class="qty-btn" onclick="App.updateQuantity(${idx}, 1)">+</button>
                       </div>
                       <button class="btn-trash" onclick="App.removeFromCart(${idx})" aria-label="Delete Selection"><i class="bi bi-trash3-fill"></i></button>
                   </div>
               </div>
           `).join('') || `<div class="py-5 text-center text-muted fs-3">Registry bag is empty.</div>`;
           if(document.getElementById('cart-sub-raw')) document.getElementById('cart-sub-raw').innerText = formatPriceString(sub);
           if(document.getElementById('cart-tax')) document.getElementById('cart-tax').innerText = formatPriceString(tax);
           if(document.getElementById('cart-total-display')) document.getElementById('cart-total-display').innerText = formatPriceString(total);
       }

       function calculateCommerceTotalLogic(sub) {
           let totalVal = Number(sub) + (Number(sub) * state.settings.vat);
           if (state.cart.reduce((a, b) => a + Number(b.qty), 0) >= 10) totalVal *= 0.8; 
           if (document.getElementById('order-type')?.value === 'pickup') totalVal *= 0.9;
           if (state.promo > 0) {
               const savings = totalVal * state.promo;
               totalVal -= savings;
               const row = document.getElementById('promo-row');
               if(row) { row.classList.remove('d-none'); document.getElementById('promo-val').innerText = `-${formatPriceString(savings)}`; }
           } else { if(document.getElementById('promo-row')) document.getElementById('promo-row').classList.add('d-none'); }
           return totalVal;
       }

       function formatPriceString(val) {
           const r = Number(val) * state.rates[state.currency];
           return isNaN(r) ? "0.00 " + state.currency : `${r.toFixed(2)} ${state.currency}`;
       }

       // --- PUBLIC MONOLITH API ---
       const publicAPI = {
           init: function() {
               normalizeCommerceState(); 
               fetchCatalogueApiData(); 

               // [FIXED] STRICT ROUTER Clean-up
               const router = () => {
                   const hv = (window.location.hash || '#home').substring(1);
                   const sections = document.querySelectorAll('.module-section');
                   sections.forEach(m => { m.classList.remove('active'); m.style.display = 'none'; });
                   const target = document.getElementById(hv + '-module');
                   if (target) { target.classList.add('active'); target.style.display = 'block'; }
                   if(hv === 'cart') renderCartView();
                   if(hv === 'wishlist') renderWishlistView();
                   window.scrollTo({ top: 0, behavior: 'smooth' });
                   applyActiveTranslation();
               };
               window.addEventListener('hashchange', router); router();

               setupFlatpickrModules(); 
               updateGlobalCounterDisplays();
               applyActiveTranslation(); 
               checkPushStatus();
               if ("geolocation" in navigator) {
                   navigator.geolocation.getCurrentPosition(pos => { state.coords = `${pos.coords.latitude},${pos.coords.longitude}`; });
               }
               AOS.init({ duration: 1000, once: true });

               // FAIL-SAFE OVERLAY HIDE
               setTimeout(() => {
                   const overlay = document.getElementById('maint-overlay');
                   if(overlay) overlay.style.display = 'none';
               }, 4000);
           },

           // [FIXED] Language Switcher with Reactive Re-render
           changeLanguage: function(v) {
               state.lang = v;
               localStorage.setItem('sushi_lang', v);
               applyActiveTranslation();
               renderGridView(state.catalog); 
               if(window.location.hash === '#cart') renderCartView();
               if(window.location.hash === '#wishlist') renderWishlistView();
               this.showToast(`Language synced: ${v.toUpperCase()}`);
           },

           updateQuantity: function(idx, d) {
               const item = state.cart[idx];
               if (!item) return;
               item.qty += d;
               if (item.qty <= 0) state.cart.splice(idx, 1);
               syncMonolithSession();
               renderCartView();
           },

           removeFromCart: function(idx) {
               if (state.cart[idx]) { state.cart.splice(idx, 1); syncMonolithSession(); renderCartView(); }
           },

           applyCoupon: function() {
               const code = document.getElementById('promo-input').value.toUpperCase();
               if(code === 'SUSHI10') { state.promo = 0.10; this.showToast('Coupon SUSHI10 Sync!'); renderCartView(); }
               else { alert('Registry Error: Coupon sequence invalid.'); }
           },

           addToCart: function(globalIdx) {
               const product = state.catalog[globalIdx];
               if (!product) return;
               const exist = state.cart.find(c => c.title === product.title);
               if (exist) exist.qty += 1;
               else state.cart.push({ ...product, qty: 1, variant: state.selectedVariant.color });
               syncMonolithSession();
               this.showToast(`${product.title} Integrated.`);
           },

           openQuickView: function(idx) {
               const p = state.catalog[idx];
               if (!p) return; 
               state.quickViewQty = 1;
               const hasVariants = p.tags && (p.tags.includes('color') || p.tags.includes('size'));
               const variantHtml = hasVariants ? `
                   <p class='small fw-bold text-uppercase mb-3 tracking-widest opacity-50'>Choose Selection variant</p>
                   <div class="swatch-group mb-5">
                       <div class="swatch-item bg-dark active" onclick="App.setVariantSelection(this, 'Traditional')"></div>
                       <div class="swatch-item bg-danger" onclick="App.setVariantSelection(this, 'Spicy')"></div>
                       <div class="swatch-item bg-success" onclick="App.setVariantSelection(this, 'Vegan')"></div>
                   </div>` : '';

               document.getElementById('quickview-content').innerHTML = `
                   <div class="row g-0"><div class="col-md-6"><img src="${p.img}" class="img-fluid h-100" style="object-fit:cover" /></div>
                   <div class="col-md-6 p-4 p-md-5">
                       <h1 class="fw-bold mb-1 display-5" style="letter-spacing:-2px">${p.title}</h1>
                       <div class="text-danger display-5 fw-bold mb-5">${formatPriceString(p.price)}</div>
                       ${variantHtml}
                       <p class='small fw-bold text-uppercase mb-3 tracking-widest opacity-50'>Batch Quantity</p>
                       <div class='d-flex align-items-center gap-4 mb-5'>
                           <div class='qty-box shadow-sm border'>
                               <button class='qty-btn' onclick='App.updateQuickViewQty(-1)'>-</button>
                               <span class='fw-bold px-3 fs-3' id='qv-qty-display'>1</span>
                               <button class='qty-btn' onclick='App.updateQuickViewQty(1)'>+</button>
                           </div>
                       </div>
                       <button class="btn btn-danger w-100 py-5 rounded-pill fw-bold fs-3 shadow-2xl transition-all" onclick="App.addQuickViewToCart(${idx})">Sync Selection</button>
                   </div></div>`;
               new bootstrap.Modal(document.getElementById('quickViewModal')).show();
           },

           updateQuickViewQty: function(d) { state.quickViewQty = Math.max(1, state.quickViewQty + d); document.getElementById('qv-qty-display').innerText = state.quickViewQty; },

           addQuickViewToCart: function(idx) {
               const target = state.catalog[idx];
               const exist = state.cart.find(c => c.title === target.title);
               if (exist) exist.qty += state.quickViewQty;
               else state.cart.push({ ...target, qty: state.quickViewQty, variant: state.selectedVariant.color });
               syncMonolithSession();
               bootstrap.Modal.getInstance(document.getElementById('quickViewModal'))?.hide();
           },

           addToCompare: function(idx) {
               const p = state.catalog[idx];
               if (!p) return;
               if (state.compare.length >= 2) state.compare.shift();
               state.compare.push(p);
               if (state.compare.length === 2) {
                   const b = document.getElementById('compare-body');
                   const c = state.compare;
                   b.innerHTML = `<tr><th>Comparative</th><td><img src="${c[0].img}" width="150" class="rounded-5" /></td><td><img src="${c[1].img}" width="150" class="rounded-5" /></td></tr>
                                <tr><th>Title</th><td class="fw-bold">${c[0].title}</td><td class="fw-bold">${c[1].title}</td></tr>
                                <tr><th>Action Bridge</th><td><button class="btn btn-danger btn-sm rounded-pill px-4" onclick="App.addToCartByName('${c[0].title}')">Add Left</button></td>
                                                     <td><button class="btn btn-danger btn-sm rounded-pill px-4" onclick="App.addToCartByName('${c[1].title}')">Add Right</button></td></tr>`;
                   new bootstrap.Modal(document.getElementById('compareModal')).show();
               } else { this.showToast('Select one more box.'); }
           },

           toggleWishlist: function(idx) {
               const p = state.catalog[idx];
               if (!p) return;
               const wIdx = state.wishlist.findIndex(w => w.title === p.title);
               if (wIdx > -1) { state.wishlist.splice(wIdx, 1); this.showToast('Removed.'); }
               else { state.wishlist.push(p); this.showToast('Saved to Registry!'); }
               syncMonolithSession();
               renderGridView(state.catalog); 
               if(window.location.hash === '#wishlist') renderWishlistView();
           },

           parseCatalog: function(data) {
               state.catalog = (data.feed.entry || []).map(p => ({
                   title: p.title.$t,
                   img: p.media$thumbnail.url.replace(/\/s[0-9]+(-c)?\//, '/w1000-h800-c/'),
                   price: parseFloat(p.category?.find(c => c.term.startsWith('price-'))?.term.split('-')[1] || "0"),
                   tags: p.category ? p.category.map(c => c.term) : [],
                   sku: p.category?.find(c => c.term.startsWith('sku-'))?.term.split('-')[1] || 'SKU-' + Math.random().toString(36).substr(2, 8).toUpperCase(),
                   qty: 1
               }));
               renderGridView(state.catalog);
           },

           handleSearch: function() { const q = document.getElementById('adv-search').value.toLowerCase(); renderGridView(state.catalog.filter(i => i.title.toLowerCase().includes(q) || i.sku.toString().toLowerCase().includes(q))); },
           setView: function(t) { state.view = t; renderGridView(state.catalog); },
           changeCurrency: function(c) { state.currency = c; localStorage.setItem('sushi_currency', c); renderGridView(state.catalog); if(window.location.hash === '#cart') renderCartView(); },
           toggleTheme: function() { const n = document.body.getAttribute('data-theme') === 'dark' ? 'light' : 'dark'; document.body.setAttribute('data-theme', n); localStorage.setItem('sushi_theme', n); },
           handleConditionalForm: () => { document.getElementById('addr-container').style.display = (document.getElementById('order-type').value === 'pickup') ? 'none' : 'block'; renderCartView(); },
           setVariantSelection: function(el, name) { document.querySelectorAll('.swatch-item').forEach(s => s.classList.remove('active')); el.classList.add('active'); state.selectedVariant.color = name; },
           setupNotifications: function() { if ("Notification" in window) { Notification.requestPermission().then(perm => { if (perm === "granted") { state.settings.pushEnabled = 'true'; localStorage.setItem('sushi_push', 'true'); } }); } this.closePushOptin(); },
           closePushOptin: function() { document.getElementById('push-optin').style.display = 'none'; },
           generatePDF: () => window.print(),
           showToast: (txt) => { document.getElementById('toast-msg').innerText = txt; new bootstrap.Toast(document.getElementById('ui-toast')).show(); },
           triggerSupport: () => window.open('https://wa.me/212666000000', '_blank'),
           addToCartByName: (title) => {
                const p = state.catalog.find(i => i.title === title);
                if(p) {
                    const exist = state.cart.find(c => c.title === p.title);
                    if(exist) exist.qty++; else state.cart.push({...p, qty:1});
                    syncMonolithSession();
                    publicAPI.showToast("Added from Comparison");
                }
           },
           finalizeOrder: function() {
               const n = document.getElementById('cust-name').value;
               if(!n) { alert('Name required.'); return; }
               const gps = state.coords ? `%0ALocation: http://maps.google.com/?q=${state.coords}` : '';
               const msg = `*NEW ORDER SUSHIELITE v67.0*%0AName: ${n}%0AItems: ${state.cart.length}%0ATotal: ${document.getElementById('cart-total-display').innerText}${gps}`;
               window.open(`https://wa.me/212666000000?text=${msg}`, '_blank');
           }
       };

       function syncMonolithSession() {
           localStorage.setItem('sushi_cart', JSON.stringify(state.cart));
           localStorage.setItem('sushi_wishlist', JSON.stringify(state.wishlist));
           updateGlobalCounterDisplays();
       }

       function updateGlobalCounterDisplays() {
           const cCount = state.cart.reduce((a, b) => a + Number(b.qty), 0);
           const wCount = state.wishlist.length;
           const cEl = document.getElementById('cart-count');
           const wEl = document.getElementById('wish-count');
           const wMEl = document.getElementById('wish-count-mob');
           if(cEl) cEl.innerText = cCount;
           if(wEl) wEl.innerText = wCount;
           if(wMEl) wMEl.innerText = wCount;
       }

       window.App = publicAPI;
       return publicAPI;
   })();

   // --- MONOLITH EXECUTION ---
   document.addEventListener('DOMContentLoaded', function() {
       if(window.App && typeof window.App.init === 'function') {
           window.App.init();
       }
   });
   window.addEventListener('scroll', () => {
       const p = (window.scrollY / (document.documentElement.scrollHeight - window.innerHeight)) * 100;
       const b = document.getElementById("scroll-fill");
       if(b) b.style.width = p + "%";
   });
   //
